import 'package:flutter/material.dart'; import 'package:provider/provider.dart'; import 'package:shared_preferences/shared_preferences.dart'; import 'dart:convert'; void main() => runApp(const TuranDefteriApp()); class Note { final String title; final String content; Note({required this.title, required this.content}); Map<String, dynamic> toJson() => {'title': title, 'content': content}; factory Note.fromJson(Map<String, dynamic> json) => Note(title: json['title'], content: json['content']); } class NoteProvider with ChangeNotifier { List<Note> _notes = []; List<Note> get notes => _notes; NoteProvider() { _loadNotes(); } void addNote(String title, String content) { _notes.add(Note(title: title, content: content)); _saveNotes(); notifyListeners(); } void _saveNotes() async { final prefs = await SharedPreferences.getInstance(); prefs.setString('notes', jsonEncode(_notes.map((e) => e.toJson()).toList())); } void _loadNotes() async { final prefs = await SharedPreferences.getInstance(); final String? data = prefs.getString('notes'); if (data != null) { _notes = (jsonDecode(data) as List).map((e) => Note.fromJson(e)).toList(); notifyListeners(); } } } class TuranDefteriApp extends StatelessWidget { const TuranDefteriApp({super.key}); @override Widget build(BuildContext context) { return ChangeNotifierProvider(create: (_) => NoteProvider(), child: MaterialApp(theme: ThemeData.dark().copyWith(scaffoldBackgroundColor: const Color(0xFF1B262C), primaryColor: const Color(0xFF4A7C59)), home: const HomePage())); } } class HomePage extends StatefulWidget { const HomePage({super.key}); @override State<HomePage> createState() => _HomePageState(); } class _HomePageState extends State<HomePage> { int _idx = 0; final List<Widget> _pages = [const NotesList(), const AddNote()]; @override Widget build(BuildContext context) { return Scaffold(appBar: AppBar(title: const Text('Turan Defteri')), body: _pages[_idx], bottomNavigationBar: BottomNavigationBar(currentIndex: _idx, onTap: (i) => setState(() => _idx = i), items: const [BottomNavigationBarItem(icon: Icon(Icons.list), label: 'Notlar'), BottomNavigationBarItem(icon: Icon(Icons.add), label: 'Yeni Kayıt')])); } } class NotesList extends StatelessWidget { const NotesList({super.key}); @override Widget build(BuildContext context) { final notes = context.watch<NoteProvider>().notes; return ListView.builder(itemCount: notes.length, itemBuilder: (c, i) => Card(color: const Color(0xFF2D4045), child: ListTile(title: Text(notes[i].title), subtitle: Text(notes[i].content)))); } } class AddNote extends StatefulWidget { const AddNote({super.key}); @override State<AddNote> createState() => _AddNoteState(); } class _AddNoteState extends State<AddNote> { final _t = TextEditingController(); final _c = TextEditingController(); @override Widget build(BuildContext context) { return Padding(padding: const EdgeInsets.all(16), child: Column(children: [TextField(controller: _t, decoration: const InputDecoration(labelText: 'Başlık')), TextField(controller: _c, decoration: const InputDecoration(labelText: 'İçerik')), ElevatedButton(onPressed: () { context.read<NoteProvider>().addNote(_t.text, _c.text); _t.clear(); _c.clear(); }, child: const Text('Kaydet'))])); } }